UPDATE TBSY_MEMBER /* MemberMapper.updateMember */
   SET MB_NM        = #{m.mbNm}
     , REPRESENT_NM = #{m.representNm}
     , TELNO        = #{m.telno}
     , CONT_FRYMD   = #{m.contFrymd}
     , CONT_TOYMD   = #{m.contToymd}
     , USE_YN       = IFNULL(NULLIF(#{m.useYn}, ''), 'Y')
     , MEMO         = #{m.memo}
     , UP_EMP_CD    = #{userId}
     , UP_DTM       = NOW()
 WHERE MB_ID = #{m.mbId}
